// Contract for public/data/frontend_cells.json (generated by scripts/export_frontend.py).
// Columnar: every array has meta.n_cells entries; the same index is the same cell.

export type Label = 0 | 1 | 2 | 3; // 0 not a site, 1 moon, 2 mars, 3 both (bitmask: moon=1, mars=2)
export type AppName = "spacewalk" | "rover" | "craters" | "cave";

export interface AppLayer {
  label: Label[];
  quality: number[];    // 0..1, ranking inside a label; 0 when label === 0
  score_moon: number[]; // 0..1; 0 when label === 0
  score_mars: number[]; // 0..1; 0 when label === 0
}

export interface FrontendCells {
  meta: {
    generated: string;          // ISO date
    n_cells: number;
    grid: { res_deg: 0.5; ncols: 720; nrows: 360; crs: "EPSG:4326"; cell_id: string; lat_lon: string };
    mocked: string[];           // layers that are demo data, e.g. ["craters", "elevation"]
    label_codes: Record<string, string>;
    filter_semantics: Record<string, string>;
    ranges: { temp: [number, number]; elevation: [number, number] };
    units: { temp: string; elevation: string };
  };
  cell_id: number[];    // unique, = row * 720 + col
  lat: number[];        // cell centre (.25 / .75)
  lon: number[];
  passes_all: (0 | 1)[]; // forest/urban/water screening
  temp: number[];       // deg C
  elevation: number[];  // m
  apps: Record<AppName, AppLayer>;
}

// Filter logic
// target moon: (label & 1) !== 0 | mars: (label & 2) !== 0 | both: label === 3
// several targets: any; several applications: all.
// A cell is "not a site" for an application when label === 0.
